#!/usr/bin/python3
import html, os, secrets, sqlite3
from http.cookies import SimpleCookie
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs

DB_DIR = "/var/lib/harbor-service"
DB_PATH = DB_DIR + "/release-desk.db"
CANDIDATES = [
 ("atlas", "Atlas 4.8", 0, 98, 1, 1, 1, "EU-West", "Tue 14:30 UTC"),
 ("borealis", "Borealis 2.3", 0, 99, 1, 1, 0, "EU-West", "Wed 09:00 UTC"),
 ("cascade", "Cascade 7.1", 1, 100, 1, 1, 1, "EU-West", "Thu 18:00 UTC"),
 ("drift", "Drift 5.0", 0, 96, 1, 0, 1, "US-East", "Fri 21:00 UTC"),
]
SESSIONS = {}

def initialize():
 os.makedirs(DB_DIR, mode=0o700, exist_ok=True)
 if os.path.exists(DB_PATH): os.unlink(DB_PATH)
 db=sqlite3.connect(DB_PATH)
 db.executescript("""CREATE TABLE candidates(id TEXT PRIMARY KEY,name TEXT,sev1 INTEGER,pass_rate INTEGER,security_ok INTEGER,qa_ok INTEGER,rollback_ok INTEGER,region TEXT,window_text TEXT);
 CREATE TABLE schedules(id INTEGER PRIMARY KEY AUTOINCREMENT,candidate_id TEXT NOT NULL UNIQUE,owner TEXT NOT NULL,rollback_ack INTEGER NOT NULL,deployment_note TEXT NOT NULL,status TEXT NOT NULL);""")
 db.executemany("INSERT INTO candidates VALUES (?,?,?,?,?,?,?,?,?)", CANDIDATES)
 db.commit(); db.close(); os.chmod(DB_PATH,0o600)

STYLE="""body{font-family:system-ui,sans-serif;margin:0;background:#eef2f7;color:#172033}header{background:#14213d;color:white;padding:22px 7%;display:flex;justify-content:space-between}main{max-width:980px;margin:30px auto;padding:0 22px}.sub{color:#59657a}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card,.panel{background:white;border:1px solid #ccd5e1;border-radius:12px;padding:22px;box-shadow:0 2px 7px #ccd5e1}button{background:#1769aa;color:white;border:0;border-radius:7px;padding:11px 17px;font-weight:700;cursor:pointer}.secondary{background:#526174}.pill{background:#e7edf5;border-radius:999px;padding:5px 9px;font-size:13px}.facts{display:grid;grid-template-columns:1fr 1fr;gap:11px;margin:22px 0}.fact{background:#f5f7fa;padding:12px;border-radius:7px}label{display:block;font-weight:650;margin:15px 0 6px}input[type=text],textarea{box-sizing:border-box;width:100%;padding:11px;border:1px solid #9ba8ba;border-radius:6px}textarea{height:88px}.check{display:flex;gap:9px;align-items:center}.check label{margin:0}.error{color:#a11919;font-weight:700}.success{border-left:7px solid #238636}small{color:#647087}"""
def layout(body): return f"<!doctype html><html><head><meta charset='utf-8'><title>Northstar Release Desk</title><style>{STYLE}</style></head><body><header><strong>Northstar Release Desk</strong><span>Production review board</span></header><main>{body}</main></body></html>"
def candidate(cid): return next((x for x in CANDIDATES if x[0]==cid),None)

class Handler(BaseHTTPRequestHandler):
 def log_message(self,*args): pass
 def session(self):
  jar=SimpleCookie(self.headers.get("Cookie","")); morsel=jar.get("northstar_session"); sid=morsel.value if morsel else ""
  if sid not in SESSIONS: sid=secrets.token_urlsafe(24); SESSIONS[sid]=secrets.token_urlsafe(24); self.new_sid=sid
  return sid,SESSIONS[sid]
 def send_html(self,body,code=200):
  raw=layout(body).encode(); self.send_response(code); self.send_header("Content-Type","text/html; charset=utf-8"); self.send_header("Content-Length",str(len(raw))); self.send_header("Cache-Control","no-store")
  if getattr(self,"new_sid",None): self.send_header("Set-Cookie",f"northstar_session={self.new_sid}; HttpOnly; SameSite=Strict; Path=/")
  self.end_headers(); self.wfile.write(raw)
 def do_GET(self):
  if self.path=="/health":
   raw=b"northstar-release-desk:ready"; self.send_response(200); self.send_header("Content-Length",str(len(raw))); self.end_headers(); self.wfile.write(raw); return
  sid,token=self.session(); path=self.path.split("?",1)[0]
  if path=="/":
   cards="".join(f"<section class='card'><span class='pill'>{html.escape(x[7])}</span><h2>{html.escape(x[1])}</h2><p>Regression pass: {x[3]}% &middot; Window: {html.escape(x[8])}</p><button id='candidate-{x[0]}' onclick=\"location.href='/candidate/{x[0]}'\">Review details</button></section>" for x in CANDIDATES)
   self.send_html(f"<h1>Release candidates</h1><p class='sub'>Review the evidence behind each candidate before scheduling.</p><div class='grid'>{cards}</div>"); return
  if path.startswith("/candidate/"):
   c=candidate(path.rsplit("/",1)[1])
   if not c: self.send_html("<h1>Not found</h1>",404); return
   facts=[("Open severity-1 incidents",c[2]),("Regression pass rate",f"{c[3]}%"),("Security approval","Approved" if c[4] else "Missing"),("QA approval","Approved" if c[5] else "Missing"),("Rollback rehearsal","Completed" if c[6] else "Not completed"),("Region",c[7]),("Window",c[8])]
   facts_html="".join(f"<div class='fact'><small>{html.escape(str(k))}</small><br><strong>{html.escape(str(v))}</strong></div>" for k,v in facts)
   self.send_html(f"<button class='secondary' id='back-to-board' onclick=\"location.href='/'\">Back to board</button><section class='panel'><h1>{html.escape(c[1])}</h1><div class='facts'>{facts_html}</div><button id='schedule-{c[0]}' onclick=\"location.href='/schedule/{c[0]}'\">Schedule this release</button></section>"); return
  if path.startswith("/schedule/"):
   c=candidate(path.rsplit("/",1)[1])
   if not c: self.send_html("<h1>Not found</h1>",404); return
   self.send_html(f"<section class='panel'><h1>Schedule {html.escape(c[1])}</h1><p>{html.escape(c[7])} &middot; {html.escape(c[8])}</p><form method='post' action='/schedule'><input type='hidden' name='csrf' value='{token}'><input type='hidden' name='candidate' value='{c[0]}'><label for='owner'>Change owner</label><input id='owner' name='owner' type='text' autocomplete='off'><div class='check'><input id='rollback-ack' name='rollback_ack' type='checkbox' value='yes'><label for='rollback-ack'>Rollback lead has been notified</label></div><label for='deployment-note'>Deployment note</label><textarea id='deployment-note' name='deployment_note'></textarea><button id='confirm-schedule' type='submit'>Confirm schedule</button></form></section>"); return
  self.send_html("<h1>Not found</h1>",404)
 def do_POST(self):
  sid,token=self.session()
  if self.path!="/schedule": self.send_html("<h1>Not found</h1>",404); return
  try:
   form=parse_qs(self.rfile.read(int(self.headers.get("Content-Length","0"))).decode(),keep_blank_values=True); get=lambda k:form.get(k,[""])[0]
   cid,owner,note=get("candidate"),get("owner").strip(),get("deployment_note").strip(); c=candidate(cid)
   eligible=c and c[2]==0 and c[3]>=97 and c[4] and c[5] and c[6] and c[7]=="EU-West"
   if get("csrf")!=token or not eligible or owner!="Mira Chen" or get("rollback_ack")!="yes" or note!="Proceed after final telemetry snapshot":
    self.send_html("<section class='panel'><h1>Schedule not accepted</h1><p class='error'>The candidate or confirmation details do not satisfy the release policy.</p><button onclick=\"location.href='/'\">Return to board</button></section>",400); return
   db=sqlite3.connect(DB_PATH); db.execute("INSERT INTO schedules(candidate_id,owner,rollback_ack,deployment_note,status) VALUES(?,?,?,?,?)",(cid,owner,1,note,"scheduled")); db.commit(); db.close()
   self.send_html(f"<section class='panel success'><h1 id='confirmation'>Release scheduled</h1><p><strong>{html.escape(c[1])}</strong> is scheduled for {html.escape(c[8])} in {html.escape(c[7])}.</p><p>Change owner: {html.escape(owner)}</p><p>Rollback lead: notified</p><p>Deployment note: {html.escape(note)}</p></section>")
  except (sqlite3.IntegrityError,ValueError): self.send_html("<h1>Schedule not accepted</h1><p class='error'>This release already has a schedule.</p>",409)

if __name__=="__main__": initialize(); ThreadingHTTPServer(("127.0.0.1",8099),Handler).serve_forever()
